import{_ as e,o as r,c as l,a2 as i}from"./chunks/framework.CNQbXYGB.js";const p=JSON.parse('{"title":"海光 DCU 微架构与算子优化指南","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function t(h,a,n,c,d,s){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="海光-dcu-微架构与算子优化指南" tabindex="-1">海光 DCU 微架构与算子优化指南 <a class="header-anchor" href="#海光-dcu-微架构与算子优化指南" aria-label="Permalink to &quot;海光 DCU 微架构与算子优化指南&quot;">​</a></h1><p>欢迎来到 <strong>DCU Microarchitecture &amp; Kernel Optimization Guide</strong>！<br> 本站服务于**“面向下一代海光 DCU 的微架构研究与大模型推理优化”<strong>研究专题，采用</strong>“先微架构原理 → 再 Profiling 工具链 → 再底层/高级算子实战 → 最后大模型推理优化”**的四段式体系编写。</p><hr><h2 id="研究入口" tabindex="-1">研究入口 <a class="header-anchor" href="#研究入口" aria-label="Permalink to &quot;研究入口&quot;">​</a></h2><ul><li><a href="./01-overview/software-stack.html">读原理</a>　理解执行、存储和调度。</li><li><a href="./labs/">跑实验</a>　按问题查找实验与复现命令。</li><li><a href="./baselines/bw100-gfx936.html">查 BW100 实测基线</a>　下载环境、逐轮计时、PMC 与 ISA。</li></ul><h2 id="研究内容" tabindex="-1">研究内容 <a class="header-anchor" href="#研究内容" aria-label="Permalink to &quot;研究内容&quot;">​</a></h2><h3 id="专题实施方案" tabindex="-1"><a href="./00-plan/research-plan.html">专题实施方案</a> <a class="header-anchor" href="#专题实施方案" aria-label="Permalink to &quot;[专题实施方案](00-plan/research-plan.md)&quot;">​</a></h3><ul><li>项目定位、双主线技术路线、四大研究方向与 2027 年核心交付目标。</li></ul><h3 id="第一部分-dcu-微架构原理" tabindex="-1">第一部分：DCU 微架构原理 <a class="header-anchor" href="#第一部分-dcu-微架构原理" aria-label="Permalink to &quot;第一部分：DCU 微架构原理&quot;">​</a></h3><p>前四节用同一个 1000 元素的向量加法串起执行模型、计算路径、存储和调度。第五节用独立例子讲 MMAC，最后用三张白板图复盘。每节有一道思考题。</p><ol><li><a href="./01-overview/software-stack.html">1.1 从 Kernel 启动到 CU</a> — 跑通第一个向量加法，验算启动了多少线程。</li><li><a href="./02-compute/cu-and-simt.html">1.2 CU、Wavefront 与计算路径</a> — 从向量加法汇编里找出哪些线程参与执行。</li><li><a href="./03-memory/memory-hierarchy.html">1.3 数据路径、缓存与同步</a> — 跟踪数组元素的位置，查缓存容量并测加载延迟。</li><li><a href="./04-scheduling/occupancy-and-roofline.html">1.4 调度、Occupancy 与延迟隐藏</a> — 只改 LDS 预留量，观察能同时驻留多少 wave。</li><li><a href="./02-compute/mmac.html">1.5 MMAC 矩阵乘加</a> — 手算小矩阵，在设备汇编里找到矩阵乘加指令。</li><li><a href="./01-overview/whiteboard-review.html">1.6 三分钟白板复述</a> — 改一次 Block 大小，用运行结果验证自己的预测。</li></ol><h3 id="第二部分-profiling-与性能分析工具链" tabindex="-1">第二部分：Profiling 与性能分析工具链 <a class="header-anchor" href="#第二部分-profiling-与性能分析工具链" aria-label="Permalink to &quot;第二部分：Profiling 与性能分析工具链&quot;">​</a></h3><ol><li><a href="./profiling/01-toolchain-overview.html">2.1 工具链全景与软件栈探测</a> — <code>torch.profiler</code>、<code>hipprof</code>、ISA 导出与容器软件栈/硬件规格探测。</li><li><a href="./profiling/02-hipprof-and-parser.html">2.2 硬件 PMC 采集与自研解析工具</a> — <code>hipprof --pmc</code> 指标速查与自研 <code>parse_hipprof_pmc.py</code> 解析工具。</li><li><a href="./profiling/03-isa-and-sim.html">2.3 ISA 反汇编分析与仿真（DCUSIM 待补充）</a> — <code>.s</code> 汇编 5 大检查点与 DCUSIM 预留章节。</li></ol><h3 id="第三部分-底层微基准与算子实战" tabindex="-1">第三部分：底层微基准与算子实战 <a class="header-anchor" href="#第三部分-底层微基准与算子实战" aria-label="Permalink to &quot;第三部分：底层微基准与算子实战&quot;">​</a></h3><p>从 <a href="./labs/">实验索引</a> 查看 E01–E10 的研究问题、复测状态和入口。首次运行先看 <a href="./labs/lab-setup.html">环境准备</a>。</p><h3 id="第四部分-大模型推理优化" tabindex="-1">第四部分：大模型推理优化 <a class="header-anchor" href="#第四部分-大模型推理优化" aria-label="Permalink to &quot;第四部分：大模型推理优化&quot;">​</a></h3><ul><li><a href="./cases/llm-operators-playbook.html">算子优化案例与检查清单</a> — GEMM、融合 RMSNorm 与 LSTM Persistent 的分析入口。</li><li><a href="./roadmap.html">研究路线图</a> — 记录 BW100 复测进度以及下一步推理 shape 和跨代对照。</li></ul>',17)])])}const m=e(o,[["render",t]]);export{p as __pageData,m as default};
